window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c3caf2e49e6a0b4"]={"versions": [{"id": "FIG-1c3caf2e49e6a0b4", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Informations- und Synchronisationsfluss).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert das Verteilungs- und Synchronisationsmodell für globale Zeitbasen (<em>Global Time Base Distribution</em>) im <em>Synchronized Time Base Manager</em> (StbM, AUTOSAR Classic R4.2.2). Der StbM entkoppelt als BSW-Systemdienst die Zeitkonsumenten (SW-Cs, SecOC, Dcm, RTE) von den bus-spezifischen Synchronisationsmodulen (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) sowie der zugrundeliegenden Hardware-Zeitbasis (Gpt, Os-Counter, Ethernet-MAC-Timestamp-Units).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Time Master:</strong> Taktgebende Instanz, die die autoritative Zeit einer Time Domain generiert, lokal pflegt und über das Kommunikationsnetzwerk verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf Basis empfangener Synchronisationsnachrichten an die Masterzeit anpasst.</li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. Time Domain auf dem Bus. Unterstützt direkt synchronisierte Zeitbasen (Synch) sowie abgeleitete Offset-Zeitbasen.</li>\n<li><strong>Interne Funktionsblöcke (je Knoten):</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Timerkanal, OS-Counter oder Hardware-Counter im Ethernet-Controller).</li>\n<li><strong>Global / Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Inkremente/Ticks der Referenzuhr gespeist und aktualisiert wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Register/Capture-Einheit für Sende- (Egress) bzw. Empfangszeitpunkte (Ingress).</li>\n<li><strong>Global / Local Time Base per Time Domain (rot gerahmt):</strong> Normierte logische Zeitbasis (Sekunden, Nanosekunden, Statusbits), die dem Gesamtsystem je Time Domain bereitgestellt wird.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>r/w access</code> (Master): Bidirektionaler Zugriff via BSW/RTE (Lesen via <code>StbM_GetCurrentTime()</code>, Initialisieren/Aktualisieren via <code>StbM_SetGlobalTime()</code> / <code>StbM_UpdateGlobalTime()</code>).</li>\n<li><code>read access</code> (Slave): Ausschließlicher Lesezugriff via <code>StbM_GetCurrentTime()</code> für Applikationen/Module.</li>\n<li><code>TimeSyncMsg</code>: Übertragene Zeitsynchronisations-PDU über den jeweiligen Bus-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>).</li>\n<li><code>Blitz-Symbol</code>: Asynchrones Erfassungsereignis (Hardware-Timestamping / Interrupt bei Sende- bzw. Empfangszeitpunkt der PDU).</li>\n<li><code>init</code> / <code>update</code>: Steuerpfade zur Initialisierung der Hardware-Uhr bzw. zyklischen Abfrage von Ticks zur Extrapolation der Rohzeit.</li>\n<li>$\\oplus$ (Summationsstelle am Slave): Differenzbildung und Korrekturrechnung (Offset-/Ratenkorrektur) zwischen externem Master-Zeitstempel und lokalem Rohzeitstempel.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Time Master (Sende- und Fortschreibepfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freilauf:</strong> <code>Global Time Base Raw</code> initialisiert (<code>init</code>) die <code>Time Base Reference Clock</code>. Zyklische Ticks aktualisieren (<code>update</code>) fortlaufend die Rohzeit und darüber die <code>Global Time Base per Time Domain</code>.</li>\n<li><strong>Master-Zeiteinspeisung:</strong> Eine autoritative Quelle (z. B. GPS, Diagnose oder interne Systemzeit) aktualisiert die Master-Zeitbasis über den <code>r/w access</code>-Pfad.</li>\n<li><strong>Egress-Timestamping & Dispatch:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Versand der <code>TimeSyncMsg</code> wird angestoßen.</li>\n<li>Beim Verlassen des Controllers wird der Sendezeitstempel (<code>Time Stamp</code>) exakt erfasst (Trigger via Blitz-Symbol).</li>\n<li>Die Synchronisationsinformation wird über das Bussystem übertragen.</li>\n</ul>\n<p class=\"fig-p\">#### Time Slave (Empfangs- und Korrekturpfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Ingress-Timestamping:</strong> Das Eintreffen der <code>TimeSyncMsg</code> löst den Trigger (Blitz-Symbol) aus und erzeugt einen präzisen Empfangs-<code>Time Stamp</code>.</li>\n<li><strong>Kompensation & Korrektur ($\\oplus$):</strong> Der empfangene Master-Zeitstempel wird mit dem lokalen Empfangs-Zeitstempel verrechnet (Kompensation von Signallaufzeit und Berechnen des Offsets).</li>\n<li><strong>Aktualisierung der Rohzeitbasis:</strong> Das Korrekturergebnis fließt in die <code>Local Time Base Raw</code> ein.</li>\n<li><strong>Interpolation (Zwischenintervall):</strong> Zwischen zwei Synchronisationsnachrichten treibt die lokale <code>Time Base Reference Clock</code> die Rohzeit via <code>update</code> kontinuierlich voran.</li>\n<li><strong>Bereitstellung:</strong> Die extrapolierte, synchronisierte Zeit wird in <code>Local Time Base per Time Domain</code> aktualisiert und steht dem System über <code>read access</code> synchron zur Verfügung.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Restriktionen:</strong></li>\n<li>Auf Slaves führt ein Schreibaufruf (<code>StbM_SetGlobalTime()</code>) zu einem Fehler (<code>STBM_E_PARAM</code> / Det-Eintrag); der Zugriff ist strikt auf Leseoperationen beschränkt.</li>\n<li>Zeitkonsumenten müssen zwingend den Rückgabewert und das Statusbyte (<code>StbM_TimeStampType.timeBaseStatus</code>) prüfen (z. B. <code>TIMEOUT</code>, <code>GLOBAL_TIME_BASE</code>), um abgelaufene oder unpräzise extrapolierte Zeiten bei Busausfall zu erkennen.</li>\n<li><strong>Konfigurationsaspekte (StbM / TSyn):</strong></li>\n<li><strong>Rollenverteilung:</strong> <code>StbMIsSystemWideMaster</code> definiert, ob der Knoten als Master fungiert.</li>\n<li><strong>Referenzuhr-Mapping:</strong> <code>StbMLocalTimeHardware</code> bindet den StbM an einen konkreten GPT-Kanal oder OS-Counter.</li>\n<li><strong>Offset-Zeitbasen:</strong> Werden über <code>StbMOffsetTimeBaseId</code> konfiguriert; sie teilen sich die Synchronisation der Basis-Domain, besitzen jedoch einen statischen oder dynamischen Offset.</li>\n<li><strong>Jitter & Latenzkompensation:</strong></li>\n<li>Das Blitz-Symbol verdeutlicht die Notwendigkeit von Hardware-Timestamping (insbesondere bei Ethernet/IEEE 802.1AS via <code>EthTSyn</code>). Software-basierte Interrupt-Zeitstempel unterliegen Scheduling-Jitter und verletzen bei engen Toleranzen die geforderte Genauigkeitsklasse.</li>\n</ul>"}, {"id": "FIG-5d9d90eb7e0d0086", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Informations- und Synchronisationsfluss).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert das Verteilungs- und Synchronisationsmodell für globale Zeitbasen (<em>Global Time Base Distribution</em>) im <em>Synchronized Time Base Manager</em> (StbM, AUTOSAR Classic R4.2.2). Der StbM entkoppelt als BSW-Systemdienst die Zeitkonsumenten (SW-Cs, SecOC, Dcm, RTE) von den bus-spezifischen Synchronisationsmodulen (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) sowie der zugrundeliegenden Hardware-Zeitbasis (Gpt, Os-Counter, Ethernet-MAC-Timestamp-Units).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Time Master:</strong> Taktgebende Instanz, die die autoritative Zeit einer Time Domain generiert, lokal pflegt und über das Kommunikationsnetzwerk verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf Basis empfangener Synchronisationsnachrichten an die Masterzeit anpasst.</li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. Time Domain auf dem Bus. Unterstützt direkt synchronisierte Zeitbasen (Synch) sowie abgeleitete Offset-Zeitbasen.</li>\n<li><strong>Interne Funktionsblöcke (je Knoten):</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Timerkanal, OS-Counter oder Hardware-Counter im Ethernet-Controller).</li>\n<li><strong>Global / Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Inkremente/Ticks der Referenzuhr gespeist und aktualisiert wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Register/Capture-Einheit für Sende- (Egress) bzw. Empfangszeitpunkte (Ingress).</li>\n<li><strong>Global / Local Time Base per Time Domain (rot gerahmt):</strong> Normierte logische Zeitbasis (Sekunden, Nanosekunden, Statusbits), die dem Gesamtsystem je Time Domain bereitgestellt wird.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>r/w access</code> (Master): Bidirektionaler Zugriff via BSW/RTE (Lesen via <code>StbM_GetCurrentTime()</code>, Initialisieren/Aktualisieren via <code>StbM_SetGlobalTime()</code> / <code>StbM_UpdateGlobalTime()</code>).</li>\n<li><code>read access</code> (Slave): Ausschließlicher Lesezugriff via <code>StbM_GetCurrentTime()</code> für Applikationen/Module.</li>\n<li><code>TimeSyncMsg</code>: Übertragene Zeitsynchronisations-PDU über den jeweiligen Bus-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>).</li>\n<li><code>Blitz-Symbol</code>: Asynchrones Erfassungsereignis (Hardware-Timestamping / Interrupt bei Sende- bzw. Empfangszeitpunkt der PDU).</li>\n<li><code>init</code> / <code>update</code>: Steuerpfade zur Initialisierung der Hardware-Uhr bzw. zyklischen Abfrage von Ticks zur Extrapolation der Rohzeit.</li>\n<li>$\\oplus$ (Summationsstelle am Slave): Differenzbildung und Korrekturrechnung (Offset-/Ratenkorrektur) zwischen externem Master-Zeitstempel und lokalem Rohzeitstempel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Time Master (Sende- und Fortschreibepfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freilauf:</strong> <code>Global Time Base Raw</code> initialisiert (<code>init</code>) die <code>Time Base Reference Clock</code>. Zyklische Ticks aktualisieren (<code>update</code>) fortlaufend die Rohzeit und darüber die <code>Global Time Base per Time Domain</code>.</li>\n<li><strong>Master-Zeiteinspeisung:</strong> Eine autoritative Quelle (z. B. GPS, Diagnose oder interne Systemzeit) aktualisiert die Master-Zeitbasis über den <code>r/w access</code>-Pfad.</li>\n<li><strong>Egress-Timestamping & Dispatch:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Versand der <code>TimeSyncMsg</code> wird angestoßen.</li>\n<li>Beim Verlassen des Controllers wird der Sendezeitstempel (<code>Time Stamp</code>) exakt erfasst (Trigger via Blitz-Symbol).</li>\n<li>Die Synchronisationsinformation wird über das Bussystem übertragen.</li>\n</ul>\n<p class=\"fig-p\">#### Time Slave (Empfangs- und Korrekturpfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Ingress-Timestamping:</strong> Das Eintreffen der <code>TimeSyncMsg</code> löst den Trigger (Blitz-Symbol) aus und erzeugt einen präzisen Empfangs-<code>Time Stamp</code>.</li>\n<li><strong>Kompensation & Korrektur ($\\oplus$):</strong> Der empfangene Master-Zeitstempel wird mit dem lokalen Empfangs-Zeitstempel verrechnet (Kompensation von Signallaufzeit und Berechnen des Offsets).</li>\n<li><strong>Aktualisierung der Rohzeitbasis:</strong> Das Korrekturergebnis fließt in die <code>Local Time Base Raw</code> ein.</li>\n<li><strong>Interpolation (Zwischenintervall):</strong> Zwischen zwei Synchronisationsnachrichten treibt die lokale <code>Time Base Reference Clock</code> die Rohzeit via <code>update</code> kontinuierlich voran.</li>\n<li><strong>Bereitstellung:</strong> Die extrapolierte, synchronisierte Zeit wird in <code>Local Time Base per Time Domain</code> aktualisiert und steht dem System über <code>read access</code> synchron zur Verfügung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Restriktionen:</strong></li>\n<li>Auf Slaves führt ein Schreibaufruf (<code>StbM_SetGlobalTime()</code>) zu einem Fehler (<code>STBM_E_PARAM</code> / Det-Eintrag); der Zugriff ist strikt auf Leseoperationen beschränkt.</li>\n<li>Zeitkonsumenten müssen zwingend den Rückgabewert und das Statusbyte (<code>StbM_TimeStampType.timeBaseStatus</code>) prüfen (z. B. <code>TIMEOUT</code>, <code>GLOBAL_TIME_BASE</code>), um abgelaufene oder unpräzise extrapolierte Zeiten bei Busausfall zu erkennen.</li>\n<li><strong>Konfigurationsaspekte (StbM / TSyn):</strong></li>\n<li><strong>Rollenverteilung:</strong> <code>StbMIsSystemWideMaster</code> definiert, ob der Knoten als Master fungiert.</li>\n<li><strong>Referenzuhr-Mapping:</strong> <code>StbMLocalTimeHardware</code> bindet den StbM an einen konkreten GPT-Kanal oder OS-Counter.</li>\n<li><strong>Offset-Zeitbasen:</strong> Werden über <code>StbMOffsetTimeBaseId</code> konfiguriert; sie teilen sich die Synchronisation der Basis-Domain, besitzen jedoch einen statischen oder dynamischen Offset.</li>\n<li><strong>Jitter & Latenzkompensation:</strong></li>\n<li>Das Blitz-Symbol verdeutlicht die Notwendigkeit von Hardware-Timestamping (insbesondere bei Ethernet/IEEE 802.1AS via <code>EthTSyn</code>). Software-basierte Interrupt-Zeitstempel unterliegen Scheduling-Jitter und verletzen bei engen Toleranzen die geforderte Genauigkeitsklasse.</li>\n</ul>"}, {"id": "FIG-35d7f77e8530332b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Informations- und Synchronisationsfluss).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert das Verteilungs- und Synchronisationsmodell für globale Zeitbasen (<em>Global Time Base Distribution</em>) im <em>Synchronized Time Base Manager</em> (StbM, AUTOSAR Classic R4.2.2). Der StbM entkoppelt als BSW-Systemdienst die Zeitkonsumenten (SW-Cs, SecOC, Dcm, RTE) von den bus-spezifischen Synchronisationsmodulen (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) sowie der zugrundeliegenden Hardware-Zeitbasis (Gpt, Os-Counter, Ethernet-MAC-Timestamp-Units).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Time Master:</strong> Taktgebende Instanz, die die autoritative Zeit einer Time Domain generiert, lokal pflegt und über das Kommunikationsnetzwerk verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf Basis empfangener Synchronisationsnachrichten an die Masterzeit anpasst.</li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. Time Domain auf dem Bus. Unterstützt direkt synchronisierte Zeitbasen (Synch) sowie abgeleitete Offset-Zeitbasen.</li>\n<li><strong>Interne Funktionsblöcke (je Knoten):</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Timerkanal, OS-Counter oder Hardware-Counter im Ethernet-Controller).</li>\n<li><strong>Global / Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Inkremente/Ticks der Referenzuhr gespeist und aktualisiert wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Register/Capture-Einheit für Sende- (Egress) bzw. Empfangszeitpunkte (Ingress).</li>\n<li><strong>Global / Local Time Base per Time Domain (rot gerahmt):</strong> Normierte logische Zeitbasis (Sekunden, Nanosekunden, Statusbits), die dem Gesamtsystem je Time Domain bereitgestellt wird.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>r/w access</code> (Master): Bidirektionaler Zugriff via BSW/RTE (Lesen via <code>StbM_GetCurrentTime()</code>, Initialisieren/Aktualisieren via <code>StbM_SetGlobalTime()</code> / <code>StbM_UpdateGlobalTime()</code>).</li>\n<li><code>read access</code> (Slave): Ausschließlicher Lesezugriff via <code>StbM_GetCurrentTime()</code> für Applikationen/Module.</li>\n<li><code>TimeSyncMsg</code>: Übertragene Zeitsynchronisations-PDU über den jeweiligen Bus-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>).</li>\n<li><code>Blitz-Symbol</code>: Asynchrones Erfassungsereignis (Hardware-Timestamping / Interrupt bei Sende- bzw. Empfangszeitpunkt der PDU).</li>\n<li><code>init</code> / <code>update</code>: Steuerpfade zur Initialisierung der Hardware-Uhr bzw. zyklischen Abfrage von Ticks zur Extrapolation der Rohzeit.</li>\n<li>$\\oplus$ (Summationsstelle am Slave): Differenzbildung und Korrekturrechnung (Offset-/Ratenkorrektur) zwischen externem Master-Zeitstempel und lokalem Rohzeitstempel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Time Master (Sende- und Fortschreibepfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freilauf:</strong> <code>Global Time Base Raw</code> initialisiert (<code>init</code>) die <code>Time Base Reference Clock</code>. Zyklische Ticks aktualisieren (<code>update</code>) fortlaufend die Rohzeit und darüber die <code>Global Time Base per Time Domain</code>.</li>\n<li><strong>Master-Zeiteinspeisung:</strong> Eine autoritative Quelle (z. B. GPS, Diagnose oder interne Systemzeit) aktualisiert die Master-Zeitbasis über den <code>r/w access</code>-Pfad.</li>\n<li><strong>Egress-Timestamping & Dispatch:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Versand der <code>TimeSyncMsg</code> wird angestoßen.</li>\n<li>Beim Verlassen des Controllers wird der Sendezeitstempel (<code>Time Stamp</code>) exakt erfasst (Trigger via Blitz-Symbol).</li>\n<li>Die Synchronisationsinformation wird über das Bussystem übertragen.</li>\n</ul>\n<p class=\"fig-p\">#### Time Slave (Empfangs- und Korrekturpfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Ingress-Timestamping:</strong> Das Eintreffen der <code>TimeSyncMsg</code> löst den Trigger (Blitz-Symbol) aus und erzeugt einen präzisen Empfangs-<code>Time Stamp</code>.</li>\n<li><strong>Kompensation & Korrektur ($\\oplus$):</strong> Der empfangene Master-Zeitstempel wird mit dem lokalen Empfangs-Zeitstempel verrechnet (Kompensation von Signallaufzeit und Berechnen des Offsets).</li>\n<li><strong>Aktualisierung der Rohzeitbasis:</strong> Das Korrekturergebnis fließt in die <code>Local Time Base Raw</code> ein.</li>\n<li><strong>Interpolation (Zwischenintervall):</strong> Zwischen zwei Synchronisationsnachrichten treibt die lokale <code>Time Base Reference Clock</code> die Rohzeit via <code>update</code> kontinuierlich voran.</li>\n<li><strong>Bereitstellung:</strong> Die extrapolierte, synchronisierte Zeit wird in <code>Local Time Base per Time Domain</code> aktualisiert und steht dem System über <code>read access</code> synchron zur Verfügung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Restriktionen:</strong></li>\n<li>Auf Slaves führt ein Schreibaufruf (<code>StbM_SetGlobalTime()</code>) zu einem Fehler (<code>STBM_E_PARAM</code> / Det-Eintrag); der Zugriff ist strikt auf Leseoperationen beschränkt.</li>\n<li>Zeitkonsumenten müssen zwingend den Rückgabewert und das Statusbyte (<code>StbM_TimeStampType.timeBaseStatus</code>) prüfen (z. B. <code>TIMEOUT</code>, <code>GLOBAL_TIME_BASE</code>), um abgelaufene oder unpräzise extrapolierte Zeiten bei Busausfall zu erkennen.</li>\n<li><strong>Konfigurationsaspekte (StbM / TSyn):</strong></li>\n<li><strong>Rollenverteilung:</strong> <code>StbMIsSystemWideMaster</code> definiert, ob der Knoten als Master fungiert.</li>\n<li><strong>Referenzuhr-Mapping:</strong> <code>StbMLocalTimeHardware</code> bindet den StbM an einen konkreten GPT-Kanal oder OS-Counter.</li>\n<li><strong>Offset-Zeitbasen:</strong> Werden über <code>StbMOffsetTimeBaseId</code> konfiguriert; sie teilen sich die Synchronisation der Basis-Domain, besitzen jedoch einen statischen oder dynamischen Offset.</li>\n<li><strong>Jitter & Latenzkompensation:</strong></li>\n<li>Das Blitz-Symbol verdeutlicht die Notwendigkeit von Hardware-Timestamping (insbesondere bei Ethernet/IEEE 802.1AS via <code>EthTSyn</code>). Software-basierte Interrupt-Zeitstempel unterliegen Scheduling-Jitter und verletzen bei engen Toleranzen die geforderte Genauigkeitsklasse.</li>\n</ul>"}, {"id": "FIG-5fccdaa7c58ff733", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Synchronisations- und Zeitempfangspfad).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert die Verteilung und Rekonstruktion einer synchronisierten oder versetzten Zeitbasis (<em>Global Time Base Distribution</em>) auf der Empfängerseite (<em>Time Slave</em>) im <em>Synchronized Time Base Manager</em> (StbM). Der StbM empfängt über bus-spezifische Synchronisationsmodule (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) Zeitsynchronisationsnachrichten (<code>TimesyncMsg</code>) einer globalen Zeitdomäne und gleicht die lokale Zeitbasis an die übergeordnete Zeit an, um sie lokalen Software-Komponenten und BSW-Modulen über eine standardisierte Leseschnittstelle bereitzustellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. globale Zeitdomäne auf dem Kommunikationsbus, die Synchronisationsnachrichten für synchronisierte oder abgeleitete Offset-Zeitbasen bereitstellt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz / Steuergerät, das die externe Masterzeit über empfangene Nachrichten aufnimmt und seine lokale Zeitbasis diszipliniert.</li>\n<li><strong>Interne Funktionsblöcke des Time Slave:</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Kanal, OS-Counter oder Hardware-Zähler).</li>\n<li><strong>Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Ticks der lokalen Referenzuhr inkrementiert und fortgeschrieben wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Einheit zur präzisen Erfassung des Empfangszeitpunkts (Ingress-Timestamp) der Synchronisationsnachricht.</li>\n<li><strong>$\\oplus$ (Summationsstelle / Korrekturglied):</strong> Berechnungsstufe zur Ermittlung der Zeitabweichung sowie zur Offset- und Ratenkorrektur zwischen externem Zeitstempel und lokalem Rohzeitstempel.</li>\n<li><strong>Local Time Base per Time Domain (rot gerahmt):</strong> Disziplinierte, logische Zeitbasis (Sekunden, Nanosekunden, Statusbits) der jeweiligen Zeitdomäne für das lokale System.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>TimesyncMsg</code>: Eingehende Zeitsynchronisations-PDU aus dem globalen Zeitnetzwerk über den Bus-Treiber.</li>\n<li><code>Blitz-Symbol</code>: Erfassungsereignis (Hardware-Timestamping / Ingress-Interrupt) beim Eintreffen der Synchronisations-PDU.</li>\n<li><code>init</code>: Steuerpfad zur Initialisierung der lokalen Referenzuhr durch die Rohzeitbasis.</li>\n<li><code>update</code>: Zyklische Taktaktualisierung von der Referenzuhr zur Rohzeitbasis sowie Fortschreibung der logischen Zeitbasis aus der disziplinierten Rohzeitbasis.</li>\n<li><code>read access</code>: Exklusiver Lesezugriff für Applikationen (SW-Cs) und BSW-Module (z. B. via <code>StbM_GetCurrentTime()</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & lokaler Zeittakt:</strong> Die Rohzeitbasis (<code>Local Time Base Raw</code>) initialisiert (<code>init</code>) die lokale Referenzuhr (<code>Time Base Reference Clock</code>). Fortlaufende Ticks der Referenzuhr aktualisieren (<code>update</code>) zyklisch den Zählerstand der Rohzeitbasis.</li>\n<li><strong>Nachrichtenempfang & Ingress-Timestamping:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Zeitsynchronisationsnachricht (<code>TimesyncMsg</code>) trifft aus der globalen Zeitdomäne (<code>Global Time Synchronized / Offset</code>) am Slave ein.</li>\n<li>Beim physischen Eintreffen triggert ein Erfassungsereignis (Blitz-Symbol) das hardwarenahe Erfassen des präzisen Empfangszeitstempels in der Einheit <code>Time Stamp</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation & Korrektur:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Über das Summier-/Korrekturglied ($\\oplus$) wird der empfangene globale Zeitstempel mit dem lokalen Rohzeitstempel verglichen.</li>\n<li>Die resultierende zeitliche Abweichung diszipliniert die lokale Rohzeit (<code>Local Time Base Raw</code>) über Offset- und Ratenanpassungen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereitstellung der Zeitbasis:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die disziplinierte Zeit wird in die domänenspezifische lokale Zeitbasis (<code>Local Time Base per Time Domain</code>) übertragen (<code>update</code>).</li>\n<li>Lokale Zeitkonsumenten greifen über den Pfad <code>read access</code> auf die synchronisierte Zeitbasis zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Entkopplung:</strong> Das Modell beschreibt die funktionale Trennung zwischen busgebundenem Nachrichtentransport (<code>TimesyncMsg</code>), hardwarenahem Ingress-Timestamping und der lokalen Zeitdisziplinierung im StbM.</li>\n<li><strong>Zeiterfassung:</strong> Das Blitz-Symbol verdeutlicht die Notwendigkeit deterministischer, jitterarmer Zeitstempelerfassung (idealerweise Hardware-Timestamping auf Controller-/Transceiver-Ebene) beim Empfang von Synchronisationsnachrichten.</li>\n<li><strong>Zugriffsbeschränkung:</strong> Für Konsumenten auf dem Time Slave ist ausschließlich ein lesender Zugriff (<code>read access</code>) vorgesehen; eine Rückspeisung oder Manipulation der synchronisierten Zeitbasis durch lokale Applikationen ist architektonisch ausgeschlossen.</li>\n</ul>"}, {"id": "FIG-47723f2e8a008ce8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Informations- und Synchronisationsfluss).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert das Verteilungs- und Synchronisationsmodell für globale Zeitbasen (<em>Global Time Base Distribution</em>) im <em>Synchronized Time Base Manager</em> (StbM). Der StbM entkoppelt als BSW-Systemdienst die Zeitkonsumenten (SW-Cs, SecOC, Dcm, RTE) von den bus-spezifischen Synchronisationsmodulen (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) sowie der zugrundeliegenden Hardware-Zeitbasis (Gpt, Os-Counter, Ethernet-MAC-Timestamp-Units) und stellt das Zusammenspiel zwischen taktgebendem Time Master und synchronisiertem Time Slave über ein logisches Zeitnetzwerk dar.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Time Master:</strong> Taktgebende Instanz, die die autoritative Zeit einer Time Domain generiert, lokal pflegt und über das Kommunikationsnetzwerk verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf Basis empfangener Synchronisationsnachrichten an die Masterzeit anpasst.</li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. Time Domain auf dem Bus. Unterstützt direkt synchronisierte Zeitbasen sowie abgeleitete Offset-Zeitbasen.</li>\n<li><strong>Interne Funktionsblöcke (je Knoten):</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Timerkanal, OS-Counter oder Hardware-Counter im Ethernet-Controller).</li>\n<li><strong>Global / Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Inkremente/Ticks der Referenzuhr gespeist und aktualisiert wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Register/Capture-Einheit für Sende- (Egress) bzw. Empfangszeitpunkte (Ingress).</li>\n<li><strong>Global / Local Time Base per Time Domain (rot gerahmt):</strong> Normierte logische Zeitbasis (Sekunden, Nanosekunden, Statusbits), die dem Gesamtsystem je Time Domain bereitgestellt wird.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>r/w access</code> (Master): Bidirektionaler Lese- und Schreibzugriff via BSW/RTE (Lesen via <code>StbM_GetCurrentTime()</code>, Setzen/Aktualisieren via <code>StbM_SetGlobalTime()</code> / <code>StbM_UpdateGlobalTime()</code>).</li>\n<li><code>read access</code> (Slave): Ausschließlicher Lesezugriff via <code>StbM_GetCurrentTime()</code> für lokale Konsumenten.</li>\n<li><code>TimesyncMsg</code>: Übertragene Zeitsynchronisations-PDU über den jeweiligen Bus-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>).</li>\n<li><code>Blitz-Symbol</code>: Asynchrones Erfassungsereignis (Hardware-Timestamping / Interrupt bei Sende- bzw. Empfangszeitpunkt der PDU).</li>\n<li><code>init</code> / <code>update</code>: Steuerpfade zur Initialisierung der Hardware-Uhr bzw. zyklischen Abfrage von Ticks zur Extrapolation der Rohzeit.</li>\n<li>$\\oplus$ (Summationsstelle am Slave): Differenzbildung und Korrekturrechnung (Offset-/Ratenkorrektur) zwischen externem Master-Zeitstempel und lokalem Rohzeitstempel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Time Master (Sende- und Fortschreibepfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freilauf:</strong> <code>Global Time Base Raw</code> initialisiert (<code>init</code>) die <code>Time Base Reference Clock</code>. Zyklische Ticks aktualisieren (<code>update</code>) fortlaufend die Rohzeit und darüber die <code>Global Time Base per Time Domain</code>.</li>\n<li><strong>Master-Zeiteinspeisung:</strong> Eine autoritative Quelle (z. B. GPS, Diagnose oder interne Systemzeit) aktualisiert die Master-Zeitbasis über den <code>r/w access</code>-Pfad.</li>\n<li><strong>Egress-Timestamping & Dispatch:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Versand der <code>TimesyncMsg</code> wird angestoßen.</li>\n<li>Beim Verlassen des Controllers wird der Sendezeitstempel (<code>Time Stamp</code>) exakt erfasst (Trigger via Blitz-Symbol).</li>\n<li>Die Synchronisationsnachricht wird über das logische Zeitnetzwerk (<code>Global Time Synchronized / Offset</code>) an den Bus übergeben.</li>\n</ul>\n<p class=\"fig-p\">#### Time Slave (Empfangs- und Synchronisationspfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Freilauf & Ingress-Timestamping:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die lokale Rohzeitbasis (<code>Local Time Base Raw</code>) speist sich autark aus der lokalen Referenzuhr (<code>Time Base Reference Clock</code>).</li>\n<li>Beim Eintreffen der <code>TimesyncMsg</code> aus dem Netzwerk wird über das Blitz-Symbol der Empfangszeitpunkt (<code>Time Stamp</code>) erfasst.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Korrekturrechnung & Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>An der Summationsstelle ($\\oplus$) wird die Abweichung zwischen übertragenem Master-Zeitstempel und lokalem Erfassungszeitpunkt ermittelt.</li>\n<li>Die Abweichung diszipliniert die <code>Local Time Base Raw</code> (Offset- und Frequenzkorrektur).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereitstellung:</strong> Die berechnete Zeit aktualisiert (<code>update</code>) die <code>Local Time Base per Time Domain</code>, von wo aus Konsumenten sie über <code>read access</code> abrufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Asymmetrie der Rollen:</strong> Während der Time Master über <code>r/w access</code> explizit von autoritativen Quellen gesetzt werden kann (<code>StbM_SetGlobalTime</code>), besitzt der Time Slave ausschließlich lesenden Zugriff (<code>read access</code>), um die Integrität der globalen Zeit nicht zu gefährden.</li>\n<li><strong>Hardware-Timestamping:</strong> Die Blitz-Symbole an Master-Egress und Slave-Ingress betonen die Notwendigkeit von Controller- bzw. PHY-gestütztem Timestamping für anspruchsvolle Protokolle wie PTP / IEEE 802.1AS (Ethernet), um Protokoll- und Software-Jitter zu minimieren.</li>\n<li><strong>Schichten-Entkopplung:</strong> Die Aufteilung in Referenzuhr, Rohzeitbasis und Time-Domain-Zeitbasis erlaubt es dem StbM, mehrere logische Zeitdomänen (inklusive Offset-Domänen) flexibel auf physische Hardware-Timer abzubilden.</li>\n</ul>"}, {"id": "FIG-77b61c859b4bc4e2", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Datenfluss- und Architekturmodell (Informations- und Synchronisationsfluss).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm spezifiziert das Verteilungs- und Synchronisationsmodell für globale Zeitbasen (<em>Global Time Base Distribution</em>) im <em>Synchronized Time Base Manager</em> (StbM). Der StbM entkoppelt als BSW-Systemdienst die Zeitkonsumenten (SW-Cs, SecOC, Dcm, RTE) von den bus-spezifischen Synchronisationsmodulen (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) sowie der zugrundeliegenden Hardware-Zeitbasis (Gpt, Os-Counter, Ethernet-MAC-Timestamp-Units) und stellt das Zusammenspiel zwischen taktgebendem Time Master und synchronisiertem Time Slave über ein logisches Zeitnetzwerk dar.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knotenrollen & Domänen:</strong></li>\n<li><strong>Time Master:</strong> Taktgebende Instanz, die die autoritative Zeit einer Time Domain generiert, lokal pflegt und über das Kommunikationsnetzwerk verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf Basis empfangener Synchronisationsnachrichten an die Masterzeit anpasst.</li>\n<li><strong>Global Time Synchronized / Offset (blau):</strong> Logisches Zeitnetzwerk bzw. Time Domain auf dem Bus. Unterstützt direkt synchronisierte Zeitbasen sowie abgeleitete Offset-Zeitbasen.</li>\n<li><strong>Interne Funktionsblöcke (je Knoten):</strong></li>\n<li><strong>Time Base Reference Clock:</strong> Physische, kontinuierlich freilaufende Hardware- oder OS-Referenzuhr (z. B. GPT-Timerkanal, OS-Counter oder Hardware-Counter im Ethernet-Controller).</li>\n<li><strong>Global / Local Time Base Raw:</strong> Diskreter Rohzeitzähler, der direkt über Inkremente/Ticks der Referenzuhr gespeist und aktualisiert wird.</li>\n<li><strong>Time Stamp:</strong> Zeitstempel-Register/Capture-Einheit für Sende- (Egress) bzw. Empfangszeitpunkte (Ingress).</li>\n<li><strong>Global / Local Time Base per Time Domain (rot gerahmt):</strong> Normierte logische Zeitbasis (Sekunden, Nanosekunden, Statusbits), die dem Gesamtsystem je Time Domain bereitgestellt wird.</li>\n<li><strong>Schnittstellen & Interaktionspfade:</strong></li>\n<li><code>r/w access</code> (Master): Bidirektionaler Lese- und Schreibzugriff via BSW/RTE (Lesen via <code>StbM_GetCurrentTime()</code>, Setzen/Aktualisieren via <code>StbM_SetGlobalTime()</code> / <code>StbM_UpdateGlobalTime()</code>).</li>\n<li><code>read access</code> (Slave): Ausschließlicher Lesezugriff via <code>StbM_GetCurrentTime()</code> für lokale Konsumenten.</li>\n<li><code>TimesyncMsg</code>: Übertragene Zeitsynchronisations-PDU über den jeweiligen Bus-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>).</li>\n<li><code>Blitz-Symbol</code>: Asynchrones Erfassungsereignis (Hardware-Timestamping / Interrupt bei Sende- bzw. Empfangszeitpunkt der PDU).</li>\n<li><code>init</code> / <code>update</code>: Steuerpfade zur Initialisierung der Hardware-Uhr bzw. zyklischen Abfrage von Ticks zur Extrapolation der Rohzeit.</li>\n<li>$\\oplus$ (Summationsstelle am Slave): Differenzbildung und Korrekturrechnung (Offset-/Ratenkorrektur) zwischen externem Master-Zeitstempel und lokalem Rohzeitstempel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Time Master (Sende- und Fortschreibepfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freilauf:</strong> <code>Global Time Base Raw</code> initialisiert (<code>init</code>) die <code>Time Base Reference Clock</code>. Zyklische Ticks aktualisieren (<code>update</code>) fortlaufend die Rohzeit und darüber die <code>Global Time Base per Time Domain</code>.</li>\n<li><strong>Master-Zeiteinspeisung:</strong> Eine autoritative Quelle (z. B. GPS, Diagnose oder interne Systemzeit) aktualisiert die Master-Zeitbasis über den <code>r/w access</code>-Pfad.</li>\n<li><strong>Egress-Timestamping & Dispatch:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Versand der <code>TimesyncMsg</code> wird angestoßen.</li>\n<li>Beim Verlassen des Controllers wird der Sendezeitstempel (<code>Time Stamp</code>) exakt erfasst (Trigger via Blitz-Symbol).</li>\n<li>Die Synchronisationsnachricht wird über das logische Zeitnetzwerk (<code>Global Time Synchronized / Offset</code>) an den Bus übergeben.</li>\n</ul>\n<p class=\"fig-p\">#### Time Slave (Empfangs- und Synchronisationspfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Freilauf & Ingress-Timestamping:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die lokale Rohzeitbasis (<code>Local Time Base Raw</code>) speist sich autark aus der lokalen Referenzuhr (<code>Time Base Reference Clock</code>).</li>\n<li>Beim Eintreffen der <code>TimesyncMsg</code> aus dem Netzwerk wird über das Blitz-Symbol der Empfangszeitpunkt (<code>Time Stamp</code>) erfasst.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Korrekturrechnung & Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>An der Summationsstelle ($\\oplus$) wird die Abweichung zwischen übertragenem Master-Zeitstempel und lokalem Erfassungszeitpunkt ermittelt.</li>\n<li>Die Abweichung diszipliniert die <code>Local Time Base Raw</code> (Offset- und Frequenzkorrektur).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereitstellung:</strong> Die berechnete Zeit aktualisiert (<code>update</code>) die <code>Local Time Base per Time Domain</code>, von wo aus Konsumenten sie über <code>read access</code> abrufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Asymmetrie der Rollen:</strong> Während der Time Master über <code>r/w access</code> explizit von autoritativen Quellen gesetzt werden kann (<code>StbM_SetGlobalTime</code>), besitzt der Time Slave ausschließlich lesenden Zugriff (<code>read access</code>), um die Integrität der globalen Zeit nicht zu gefährden.</li>\n<li><strong>Hardware-Timestamping:</strong> Die Blitz-Symbole an Master-Egress und Slave-Ingress betonen die Notwendigkeit von Controller- bzw. PHY-gestütztem Timestamping für anspruchsvolle Protokolle wie PTP / IEEE 802.1AS (Ethernet), um Protokoll- und Software-Jitter zu minimieren.</li>\n<li><strong>Schichten-Entkopplung:</strong> Die Aufteilung in Referenzuhr, Rohzeitbasis und Time-Domain-Zeitbasis erlaubt es dem StbM, mehrere logische Zeitdomänen (inklusive Offset-Domänen) flexibel auf physische Hardware-Timer abzubilden.</li>\n</ul>"}], "trans": [{"from": "FIG-1c3caf2e49e6a0b4", "to": "FIG-5d9d90eb7e0d0086", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Schreibweise der Zeitsynchronisationsnachricht auf beiden Übertragungspfaden angepasst: <code>TimeSyncMsg</code> in <code>TimesyncMsg</code> umbenannt (beim Senden vom Time Master auf das globale Zeitnetzwerk <code>Global Time Synchronized / Offset</code> sowie beim Empfang am Time Slave).</li>\n</ul>"}, {"from": "FIG-5d9d90eb7e0d0086", "to": "FIG-35d7f77e8530332b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-35d7f77e8530332b", "to": "FIG-5fccdaa7c58ff733", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Vollständiger Entfall der Instanz <code>Time Master</code> mit sämtlichen internen Funktionsblöcken (<code>Global Time Base per Time Domain</code>, <code>Global Time Base Raw</code>, <code>Time Base Reference Clock</code>, <code>Time Stamp</code>).</li>\n<li>Entfall der Schnittstelle <code>r/w access</code> zur Master-Zeitbasis sowie aller zugehörigen internen Steuer- und Datenflusspfade (<code>init</code>, <code>update</code>).</li>\n<li>Entfall des Sende-Timestampings (Blitz-Symbol) und des Sendepfads (<code>TimesyncMsg</code>) vom Time Master in die globale Zeitdomäne <code>Global Time Synchronized / Offset</code>.</li>\n<li>Das Schaubild beschränkt sich nun auf die Empfängerseite (<code>Time Slave</code>) und die Anbindung an die globale Zeitdomäne (<code>Global Time Synchronized / Offset</code>).</li>\n</ul>"}, {"from": "FIG-5fccdaa7c58ff733", "to": "FIG-47723f2e8a008ce8", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Wiedereinführung der vollständigen Instanz <code>Time Master</code> mit allen internen Komponenten (<code>Global Time Base per Time Domain</code>, <code>Global Time Base Raw</code>, <code>Time Base Reference Clock</code>, <code>Time Stamp</code>).</li>\n<li>Wiedereinführung der externen Schnittstelle <code>r/w access</code> für Lese- und Schreibzugriffe auf die Master-Zeitbasis.</li>\n<li>Wiedereinführung der internen Steuer- und Aktualisierungspfade (<code>init</code>, <code>update</code>) des Time Masters.</li>\n<li>Wiedereinführung des Egress-Timestampings (Blitz-Symbol) und des Übertragungspfads (<code>TimesyncMsg</code>) vom Time Master in die globale Zeitdomäne <code>Global Time Synchronized / Offset</code>.</li>\n</ul>"}, {"from": "FIG-47723f2e8a008ce8", "to": "FIG-77b61c859b4bc4e2", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
